using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = [];

    public CatalogService()
    {
        _departments =
        [
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Pure and applied mathematics including statistics and data analysis." },
            new() { Id = 3, Code = "PHYS", Name = "Physics", Description = "Fundamental principles of matter, energy, and their interactions." },
            new() { Id = 4, Code = "ENG", Name = "English", Description = "Literature, writing, and language studies." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Analysis of historical events, cultures, and societies." },
            new() { Id = 6, Code = "BIO", Name = "Biology", Description = "Study of living organisms and life processes." },
        ];

        _instructors =
        [
            new() { Id = 1, Name = "Dr. Sarah Chen", Title = "Associate Professor", Bio = "Dr. Chen specializes in artificial intelligence and machine learning. She has published over 40 papers in top-tier conferences and holds two patents in natural language processing.", Email = "s.chen@university.edu", OfficeLocation = "Science Building 301" },
            new() { Id = 2, Name = "Dr. James Rodriguez", Title = "Professor", Bio = "Dr. Rodriguez is a leading researcher in theoretical mathematics with a focus on algebraic topology. He has been teaching for over 20 years.", Email = "j.rodriguez@university.edu", OfficeLocation = "Math Hall 205" },
            new() { Id = 3, Name = "Dr. Emily Watson", Title = "Assistant Professor", Bio = "Dr. Watson researches quantum mechanics and particle physics. She previously worked at CERN on the Large Hadron Collider project.", Email = "e.watson@university.edu", OfficeLocation = "Physics Lab 102" },
            new() { Id = 4, Name = "Prof. Michael Torres", Title = "Professor", Bio = "Prof. Torres is a published novelist and literary critic specializing in postmodern American fiction. He has received multiple teaching excellence awards.", Email = "m.torres@university.edu", OfficeLocation = "Humanities 415" },
            new() { Id = 5, Name = "Dr. Aisha Patel", Title = "Associate Professor", Bio = "Dr. Patel is a historian of the modern Middle East and South Asia with expertise in colonial and postcolonial studies.", Email = "a.patel@university.edu", OfficeLocation = "Liberal Arts 312" },
            new() { Id = 6, Name = "Dr. Robert Kim", Title = "Professor", Bio = "Dr. Kim is a molecular biologist researching gene expression and CRISPR technology. He leads the university's genomics lab.", Email = "r.kim@university.edu", OfficeLocation = "Life Sciences 208" },
            new() { Id = 7, Name = "Dr. Lisa Nguyen", Title = "Senior Lecturer", Bio = "Dr. Nguyen has over 15 years of industry experience in software engineering and brings practical insights to her data structures and algorithms courses.", Email = "l.nguyen@university.edu", OfficeLocation = "Science Building 305" },
            new() { Id = 8, Name = "Dr. David Okafor", Title = "Assistant Professor", Bio = "Dr. Okafor studies statistical modeling and probability theory with applications in epidemiology and climate science.", Email = "d.okafor@university.edu", OfficeLocation = "Math Hall 110" },
        ];

        _courses =
        [
            new() { Id = 1, Code = "CS101", Title = "Introduction to Computer Science", Description = "A broad introduction to computer science covering fundamental concepts including algorithms, data structures, and programming paradigms. Students will learn to think computationally and solve problems using Python.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Building 101", DepartmentId = 1, InstructorId = 1, IsFeatured = true, MaxEnrollment = 120, CurrentEnrollment = 98 },
            new() { Id = 2, Code = "CS201", Title = "Data Structures and Algorithms", Description = "In-depth study of data structures (trees, graphs, hash tables) and algorithm design techniques (divide-and-conquer, dynamic programming, greedy algorithms). Includes complexity analysis.", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", Location = "Science Building 203", DepartmentId = 1, InstructorId = 7, IsFeatured = false, MaxEnrollment = 60, CurrentEnrollment = 55 },
            new() { Id = 3, Code = "CS310", Title = "Artificial Intelligence", Description = "Introduction to AI concepts including search algorithms, knowledge representation, machine learning fundamentals, and neural networks. Hands-on projects using Python and TensorFlow.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Location = "Science Building 305", DepartmentId = 1, InstructorId = 1, IsFeatured = true, MaxEnrollment = 45, CurrentEnrollment = 44 },
            new() { Id = 4, Code = "MATH101", Title = "Calculus I", Description = "Limits, continuity, differentiation, and integration of single-variable functions. Applications to physics and engineering problems.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Math Hall 100", DepartmentId = 2, InstructorId = 2, IsFeatured = false, MaxEnrollment = 150, CurrentEnrollment = 130 },
            new() { Id = 5, Code = "MATH201", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and eigenvectors. Essential for computer science, physics, and engineering students.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Location = "Math Hall 200", DepartmentId = 2, InstructorId = 2, IsFeatured = true, MaxEnrollment = 80, CurrentEnrollment = 62 },
            new() { Id = 6, Code = "MATH305", Title = "Probability and Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, regression analysis, and Bayesian inference. Applications in data science.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Location = "Math Hall 105", DepartmentId = 2, InstructorId = 8, IsFeatured = false, MaxEnrollment = 70, CurrentEnrollment = 45 },
            new() { Id = 7, Code = "PHYS101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions with hands-on experiments and data analysis.", Credits = 4, Schedule = "Tue/Thu 9:00–10:20 AM", Location = "Physics Lab 101", DepartmentId = 3, InstructorId = 3, IsFeatured = false, MaxEnrollment = 90, CurrentEnrollment = 72 },
            new() { Id = 8, Code = "PHYS301", Title = "Quantum Mechanics", Description = "Wave-particle duality, Schrödinger equation, quantum states, measurement theory, and applications to atomic and molecular systems.", Credits = 3, Schedule = "Mon/Wed 3:30–4:50 PM", Location = "Physics Lab 201", DepartmentId = 3, InstructorId = 3, IsFeatured = true, MaxEnrollment = 35, CurrentEnrollment = 28 },
            new() { Id = 9, Code = "ENG101", Title = "English Composition", Description = "Develops critical reading and academic writing skills. Students will compose essays, research papers, and creative works while studying rhetoric and argumentation.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Location = "Humanities 201", DepartmentId = 4, InstructorId = 4, IsFeatured = false, MaxEnrollment = 30, CurrentEnrollment = 28 },
            new() { Id = 10, Code = "ENG220", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present, exploring themes of identity, freedom, and the American experience.", Credits = 3, Schedule = "Tue/Thu 2:30–3:50 PM", Location = "Humanities 310", DepartmentId = 4, InstructorId = 4, IsFeatured = false, MaxEnrollment = 35, CurrentEnrollment = 22 },
            new() { Id = 11, Code = "HIST101", Title = "World History to 1500", Description = "Major civilizations and events from prehistory through the late medieval period, covering political, social, and cultural developments across continents.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", Location = "Liberal Arts 201", DepartmentId = 5, InstructorId = 5, IsFeatured = false, MaxEnrollment = 80, CurrentEnrollment = 65 },
            new() { Id = 12, Code = "HIST250", Title = "Modern World History", Description = "From the Age of Exploration through the 21st century, examining colonialism, revolutions, world wars, and globalization.", Credits = 3, Schedule = "Mon/Wed 10:00–11:20 AM", Location = "Liberal Arts 305", DepartmentId = 5, InstructorId = 5, IsFeatured = false, MaxEnrollment = 60, CurrentEnrollment = 48 },
            new() { Id = 13, Code = "BIO101", Title = "Introduction to Biology", Description = "Foundational concepts in biology including cell structure, genetics, evolution, and ecology. Includes weekly laboratory sessions.", Credits = 4, Schedule = "Mon/Wed/Fri 8:00–8:50 AM", Location = "Life Sciences 101", DepartmentId = 6, InstructorId = 6, IsFeatured = false, MaxEnrollment = 100, CurrentEnrollment = 88 },
            new() { Id = 14, Code = "BIO310", Title = "Molecular Biology", Description = "DNA replication, transcription, translation, gene regulation, and modern techniques including PCR, gel electrophoresis, and CRISPR.", Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", Location = "Life Sciences 301", DepartmentId = 6, InstructorId = 6, IsFeatured = true, MaxEnrollment = 40, CurrentEnrollment = 32 },
        ];
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.Find(d => d.Id == id);

    public List<Instructor> GetInstructors() => _instructors;

    public Instructor? GetInstructor(int id) => _instructors.Find(i => i.Id == id);

    public List<Course> GetCourses() => _courses;

    public Course? GetCourse(int id) => _courses.Find(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public void SubmitEnrollment(EnrollmentRequest request)
    {
        _enrollments.Add(request);
    }
}

