﻿@page "/"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>University Course Catalog</PageTitle>

<div class="mb-4">
    <h1>University Course Catalog</h1>
    <p class="lead">Explore our academic offerings for the current semester. Browse departments, search courses, and submit your enrollment request.</p>
</div>

<h2 class="mb-3">⭐ Featured Courses</h2>
<div class="row mb-5">
    @foreach (var course in _featuredCourses)
    {
        var dept = Catalog.GetDepartment(course.DepartmentId);
        <div class="col-md-6 col-lg-4 mb-3">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@course.Code — @course.Title</h5>
                    <p class="card-text text-muted">@dept?.Name · @course.Credits credits</p>
                    <p class="card-text">@Truncate(course.Description, 120)</p>
                </div>
                <div class="card-footer bg-transparent">
                    <a href="/courses/@course.Id" class="btn btn-primary btn-sm">View Details</a>
                    <span class="float-end badge bg-secondary mt-1">@course.CurrentEnrollment / @course.MaxEnrollment enrolled</span>
                </div>
            </div>
        </div>
    }
</div>

<h2 class="mb-3">🏛️ Departments</h2>
<div class="row">
    @foreach (var dept in _departments)
    {
        var courseCount = Catalog.GetCoursesByDepartment(dept.Id).Count;
        <div class="col-md-6 col-lg-4 mb-3">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@dept.Name</h5>
                    <p class="card-text">@dept.Description</p>
                    <p class="card-text text-muted">@courseCount course(s) available</p>
                </div>
                <div class="card-footer bg-transparent">
                    <a href="/courses?departmentId=@dept.Id" class="btn btn-outline-primary btn-sm">View Courses</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private List<Course> _featuredCourses = [];
    private List<Department> _departments = [];

    protected override void OnInitialized()
    {
        _featuredCourses = Catalog.GetFeaturedCourses();
        _departments = Catalog.GetDepartments();
    }

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : string.Concat(text.AsSpan(0, maxLength), "…");
}

