@page "/courses"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Browse Courses</PageTitle>

<h1>Browse Courses</h1>

<form method="get" class="row g-3 mb-4">
    <div class="col-md-6">
        <label for="search" class="form-label">Search</label>
        <input type="text" id="search" name="search" value="@Search" class="form-control" placeholder="Search by title, code, or keyword…" />
    </div>
    <div class="col-md-4">
        <label for="departmentId" class="form-label">Department</label>
        <select id="departmentId" name="departmentId" class="form-select">
            <option value="">All Departments</option>
            @foreach (var dept in _departments)
            {
                if (dept.Id == DepartmentId)
                {
                    <option value="@dept.Id" selected>@dept.Name</option>
                }
                else
                {
                    <option value="@dept.Id">@dept.Name</option>
                }
            }
        </select>
    </div>
    <div class="col-md-2 d-flex align-items-end">
        <button type="submit" class="btn btn-primary w-100">Filter</button>
    </div>
</form>

@if (_courses.Count == 0)
{
    <div class="alert alert-info">No courses found matching your criteria.</div>
}
else
{
    <p class="text-muted mb-3">Showing @_courses.Count course(s)</p>

    <table class="table table-striped table-hover">
        <thead>
            <tr>
                <th>Code</th>
                <th>Title</th>
                <th>Department</th>
                <th>Credits</th>
                <th>Schedule</th>
                <th>Enrollment</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in _courses)
            {
                var dept = Catalog.GetDepartment(course.DepartmentId);
                <tr>
                    <td><strong>@course.Code</strong></td>
                    <td>@course.Title</td>
                    <td>@dept?.Name</td>
                    <td>@course.Credits</td>
                    <td>@course.Schedule</td>
                    <td>
                        @course.CurrentEnrollment / @course.MaxEnrollment
                        @if (course.CurrentEnrollment >= course.MaxEnrollment)
                        {
                            <span class="badge bg-danger ms-1">Full</span>
                        }
                    </td>
                    <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }

    private List<Department> _departments = [];
    private List<Course> _courses = [];

    protected override void OnInitialized()
    {
        _departments = Catalog.GetDepartments();
        _courses = Catalog.SearchCourses(Search, DepartmentId);
    }
}

@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

@if (_course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <h1>Course Not Found</h1>
    <p>The requested course does not exist.</p>
    <a href="/courses" class="btn btn-primary">Back to Courses</a>
}
else
{
    <PageTitle>@_course.Code — @_course.Title</PageTitle>

    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/courses?departmentId=@_course.DepartmentId">@_department?.Name</a></li>
            <li class="breadcrumb-item active" aria-current="page">@_course.Code</li>
        </ol>
    </nav>

    <div class="row">
        <div class="col-lg-8">
            <h1>@_course.Code — @_course.Title</h1>

            <div class="mb-4">
                <span class="badge bg-primary me-2">@_course.Credits Credits</span>
                <span class="badge bg-secondary me-2">@_department?.Code</span>
                @if (_course.CurrentEnrollment >= _course.MaxEnrollment)
                {
                    <span class="badge bg-danger">Full</span>
                }
                else
                {
                    <span class="badge bg-success">Open</span>
                }
            </div>

            <h4>Description</h4>
            <p>@_course.Description</p>

            <h4>Schedule &amp; Location</h4>
            <table class="table table-bordered w-auto">
                <tr>
                    <th>Schedule</th>
                    <td>@_course.Schedule</td>
                </tr>
                <tr>
                    <th>Location</th>
                    <td>@_course.Location</td>
                </tr>
                <tr>
                    <th>Enrollment</th>
                    <td>@_course.CurrentEnrollment / @_course.MaxEnrollment students</td>
                </tr>
            </table>

            @if (_course.CurrentEnrollment < _course.MaxEnrollment)
            {
                <a href="/enroll?courseId=@_course.Id" class="btn btn-primary mt-2">Request Enrollment</a>
            }
        </div>

        <div class="col-lg-4">
            @if (_instructor is not null)
            {
                <div class="card">
                    <div class="card-header">
                        <h5 class="mb-0">Instructor</h5>
                    </div>
                    <div class="card-body">
                        <h5>@_instructor.Name</h5>
                        <p class="text-muted">@_instructor.Title</p>
                        <p>@_instructor.Bio</p>
                        <hr />
                        <p class="mb-1"><strong>Email:</strong> @_instructor.Email</p>
                        <p class="mb-0"><strong>Office:</strong> @_instructor.OfficeLocation</p>
                    </div>
                </div>
            }
        </div>
    </div>
}

