@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>
<p>Fill out the form below to request enrollment in a course. You will receive a confirmation once your request is processed.</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Thank you, <strong>@_model.FullName</strong>. Your enrollment request for
            <strong>@(_selectedCourse?.Code) — @(_selectedCourse?.Title)</strong> has been received.</p>
        <hr />
        <p class="mb-0">You will receive a confirmation at your university email. <a href="/enroll">Submit another request</a> or <a href="/courses">browse more courses</a>.</p>
    </div>
}
else
{
    <div class="row">
        <div class="col-lg-8">
            <form method="post" @formname="enrollment" @onsubmit="HandleSubmit">
                <AntiforgeryToken />

                <div class="mb-3">
                    <label for="fullName" class="form-label">Full Name <span class="text-danger">*</span></label>
                    <input type="text" id="fullName" name="_model.FullName" value="@_model.FullName" class="form-control" required />
                    @if (_errors.ContainsKey(nameof(_model.FullName)))
                    {
                        <div class="text-danger mt-1">@_errors[nameof(_model.FullName)]</div>
                    }
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID <span class="text-danger">*</span></label>
                    <input type="text" id="studentId" name="_model.StudentId" value="@_model.StudentId" class="form-control" placeholder="e.g., CS123456" required />
                    @if (_errors.ContainsKey(nameof(_model.StudentId)))
                    {
                        <div class="text-danger mt-1">@_errors[nameof(_model.StudentId)]</div>
                    }
                </div>

                <div class="mb-3">
                    <label for="email" class="form-label">Email</label>
                    <input type="email" id="email" name="_model.Email" value="@_model.Email" class="form-control" placeholder="your.name@university.edu" />
                    @if (_errors.ContainsKey(nameof(_model.Email)))
                    {
                        <div class="text-danger mt-1">@_errors[nameof(_model.Email)]</div>
                    }
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course <span class="text-danger">*</span></label>
                    <select id="courseId" name="_model.CourseId" class="form-select" required>
                        <option value="0">— Select a course —</option>
                        @foreach (var course in _courses)
                        {
                            var dept = Catalog.GetDepartment(course.DepartmentId);
                            if (course.Id == _model.CourseId)
                            {
                                <option value="@course.Id" selected>@course.Code — @course.Title (@dept?.Code)</option>
                            }
                            else
                            {
                                <option value="@course.Id">@course.Code — @course.Title (@dept?.Code)</option>
                            }
                        }
                    </select>
                    @if (_errors.ContainsKey(nameof(_model.CourseId)))
                    {
                        <div class="text-danger mt-1">@_errors[nameof(_model.CourseId)]</div>
                    }
                </div>

                <div class="mb-3">
                    <label for="comments" class="form-label">Comments</label>
                    <textarea id="comments" name="_model.Comments" class="form-control" rows="3">@_model.Comments</textarea>
                </div>

                <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
            </form>
        </div>
    </div>
}

@code {
    [SupplyParameterFromQuery] public int? CourseId { get; set; }
    [SupplyParameterFromForm] private EnrollmentRequest _model { get; set; } = new();

    private List<Course> _courses = [];
    private Course? _selectedCourse;
    private bool _submitted;
    private Dictionary<string, string> _errors = new();

    protected override void OnInitialized()
    {
        _courses = Catalog.GetCourses();

        if (CourseId.HasValue && _model.CourseId == 0)
        {
            _model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        _errors.Clear();

        var validationResults = new List<System.ComponentModel.DataAnnotations.ValidationResult>();
        var context = new System.ComponentModel.DataAnnotations.ValidationContext(_model);
        if (!System.ComponentModel.DataAnnotations.Validator.TryValidateObject(_model, context, validationResults, true))
        {
            foreach (var result in validationResults)
            {
                foreach (var member in result.MemberNames)
                {
                    _errors.TryAdd(member, result.ErrorMessage ?? "Invalid value.");
                }
            }
            return;
        }

        _selectedCourse = Catalog.GetCourse(_model.CourseId);
        Catalog.SubmitEnrollment(_model);
        _submitted = true;
    }
}
